from fastapi import FastAPI, APIRouter
from fastapi.testclient import TestClient
from fastapi.exceptions import FastAPIError

def test_empty_prefix_empty_path():
    try:
        app = FastAPI()
        router = APIRouter() # prefix=""

        @router.get("") # path=""
        async def root():
            return {"message": "Hello World"}

        app.include_router(router)
        print("Successfully included router with empty prefix and empty path")
    except FastAPIError as e:
        print(f"Caught expected FastAPIError: {e}")
        raise e
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

if __name__ == "__main__":
    try:
        test_empty_prefix_empty_path()
        print("Test passed (no FastAPIError raised)!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

